#!/usr/bin/env python3
"""
Round 111b (tiles), 29 September 2026. Fixes for the nine scripts that failed
in the refresh of 29 September, and the new ForestAtRisk build.

  aqueduct          crop table read a page at a time through GFW's query when
                    the data lake (403) and the csv download (500) refuse
  atlas_insets      a map with no conflicts picture keeps a count, not a list;
                    counting it no longer stops the run
  fertility_policy  reads the UN's 2019 fertility policy country data (the
                    2021 file has no fertility-level question); headings over
                    several rows joined; countries by ISO, UN number or name
  fish_rivers       finds the layer when ogrinfo prints "Layer: name (type)"
  ftw_overview      lists source.coop with list-type=2 and continuation tokens
                    (it went round the first page for 160 minutes)
  ifl               reads the authors' GeoPackages (intactforests.org) first;
                    GFW's newest listed version after (its "latest" is 404)
  inpe_fire         two builds joined: every fire at every zoom, the full
                    record from zoom 6 (84 MB, was 155 MB)
  public_harm       IMF: a plain value was unpacked as a pair
  slavery_world     UNODC's new data portal address; CBP asked as a browser,
                    and its refusal no longer fails the run
  forestatrisk      new: ForestAtRisk's probability of deforestation 2020
                    (Cirad, EC JRC), shown with permission

Whole files, each written only if it differs.
"""
import base64, pathlib

FILES = {'scripts/ftw_overview.py': '', 'scripts/public_harm.py': '', 'scripts/atlas_insets.py': '', 'scripts/fish_rivers.py': '', 'scripts/inpe_fire.py': '', 'scripts/ifl.py': '', 'scripts/fertility_policy.py': '', 'scripts/slavery_world.py': '', 'scripts/aqueduct.py': '', 'scripts/forestatrisk.py': ''}


def main():
    for p, b in FILES.items():
        data = base64.b64decode(b)
        f = pathlib.Path(p)
        if f.exists() and f.read_bytes() == data:
            print(f"round111b: {p} already up to date")
            continue
        f.parent.mkdir(parents=True, exist_ok=True)
        f.write_bytes(data)
        print(f"round111b: wrote {p}")


if __name__ == "__main__":
    main()
